using System;using System.Collections.Concurrent;using System.IO;using System.Linq;using System.Threading;using System.Threading.Tasks;using Microsoft.Kinect;using NetMQ;using NetMQ.Sockets;using Newtonsoft.Json;
class P{class M{public string T,J;public byte[] B;}static BlockingCollection<M>q=new BlockingCollection<M>(100);static volatile bool go=true;static KinectSensor k;
static void Put(string t,string j,byte[]b=null){q.TryAdd(new M{T=t,J=j,B=b??new byte[0]});}
static void Main(){Console.CancelKeyPress+=(s,e)=>{e.Cancel=true;go=false;};k=KinectSensor.KinectSensors.FirstOrDefault(x=>x.Status==KinectStatus.Connected);if(k==null){Console.Error.WriteLine("No Kinect v1; check power, USB and SDK driver");return;}
k.ColorStream.Enable(ColorImageFormat.RgbResolution640x480Fps30);k.DepthStream.Enable(DepthImageFormat.Resolution320x240Fps30);k.SkeletonStream.Enable();k.ColorFrameReady+=Color;k.DepthFrameReady+=Depth;k.SkeletonFrameReady+=Skeleton;
using(var pub=new PublisherSocket())using(var ctl=new PullSocket("@tcp://127.0.0.1:5558")){pub.Bind(Environment.GetEnvironmentVariable("KINECT_ZMQ_PUB")??"tcp://*:5557");k.Start();Console.WriteLine("PUB :5557; brightness PULL :5558; Ctrl-C stops");var stop=new CancellationTokenSource();Stream audio=null;try{audio=k.AudioSource.Start();Task.Run(()=>Audio(audio,stop.Token));}catch(Exception e){Console.Error.WriteLine("Audio unavailable: "+e.Message);}
try{while(go){string cmd;while(ctl.TryReceiveFrameString(TimeSpan.Zero,out cmd))Control(cmd);M m;while(q.TryTake(out m))pub.SendMoreFrame(m.T).SendMoreFrame(m.J).SendFrame(m.B);Thread.Sleep(2);}}finally{stop.Cancel();try{audio?.Dispose();}catch{}k.Stop();}}NetMQConfig.Cleanup();}
static void Color(object s,ColorImageFrameReadyEventArgs e){using(var f=e.OpenColorImageFrame()){if(f==null)return;byte[]b=new byte[f.PixelDataLength];f.CopyPixelDataTo(b);Put("kinect.color.bgra",JsonConvert.SerializeObject(new{schema="kinect.color.v1",width=f.Width,height=f.Height,format="BGRA32",timestamp=f.Timestamp}),b);}}
static void Depth(object s,DepthImageFrameReadyEventArgs e){using(var f=e.OpenDepthImageFrame()){if(f==null)return;short[]p=new short[f.PixelDataLength];f.CopyPixelDataTo(p);byte[]b=new byte[p.Length*2];Buffer.BlockCopy(p,0,b,0,b.Length);Put("kinect.depth.u16",JsonConvert.SerializeObject(new{schema="kinect.depth.v1",width=f.Width,height=f.Height,format="little-endian depth/player-index ushort",timestamp=f.Timestamp}),b);}}
static void Skeleton(object s,SkeletonFrameReadyEventArgs e){using(var f=e.OpenSkeletonFrame()){if(f==null)return;Skeleton[]a=new Skeleton[f.SkeletonArrayLength];f.CopySkeletonDataTo(a);var sk=a.Where(x=>x.TrackingState!=SkeletonTrackingState.NotTracked).Select(x=>new{id=x.TrackingId,state=x.TrackingState.ToString(),position=new{x=x.Position.X,y=x.Position.Y,z=x.Position.Z},joints=x.Joints.Where(j=>j.TrackingState!=JointTrackingState.NotTracked).Select(j=>new{name=j.JointType.ToString(),state=j.TrackingState.ToString(),x=j.Position.X,y=j.Position.Y,z=j.Position.Z})});Put("kinect.skeleton.json",JsonConvert.SerializeObject(new{schema="kinect.skeleton.v1",timestamp=f.Timestamp,skeletons=sk}));}}
static void Audio(Stream a,CancellationToken t){byte[]b=new byte[3200];long n=0;while(!t.IsCancellationRequested){int c;try{c=a.Read(b,0,b.Length);}catch{break;}if(c<=0)break;byte[]d=new byte[c];Buffer.BlockCopy(b,0,d,0,c);Put("kinect.audio.pcm16",JsonConvert.SerializeObject(new{schema="kinect.audio.v1",sequence=n++,sampleRate=16000,channels=1,format="PCM16LE"}),d);}}
static void Control(string x){try{var j=Newtonsoft.Json.Linq.JObject.Parse(x);if((string)j["command"]!="brightness")return;double v=(double)j["value"];if(v<0||v>1)throw new ArgumentOutOfRangeException("value");k.ColorStream.CameraSettings.Brightness=(float)v;Put("kinect.status",JsonConvert.SerializeObject(new{schema="kinect.status.v1",brightness=v}));}catch(Exception e){Console.Error.WriteLine("Control error: "+e.Message);}}}